CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'active', timezone text NOT NULL DEFAULT 'UTC', approval_policy text NOT NULL DEFAULT 'solo_owner', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL,role text NOT NULL CHECK(role IN('Owner','Admin','Editor','Viewer','Billing')),status text NOT NULL DEFAULT 'active',PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash text PRIMARY KEY,user_id text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brands(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),version integer NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,version));
CREATE TABLE IF NOT EXISTS emails(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),title text NOT NULL,doc_version integer NOT NULL DEFAULT 1,spec jsonb NOT NULL,created_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS revisions(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),email_id uuid NOT NULL,revision_no integer NOT NULL,spec jsonb NOT NULL,html text NOT NULL,plaintext text NOT NULL,artifact_hash text NOT NULL,manifest jsonb NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,email_id,revision_no),FOREIGN KEY(workspace_id,email_id) REFERENCES emails(workspace_id,id));
CREATE TABLE IF NOT EXISTS operations(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),type text NOT NULL,state text NOT NULL DEFAULT 'queued',input jsonb NOT NULL,result jsonb,error jsonb,created_by text NOT NULL,started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS idempotency(workspace_id uuid NOT NULL REFERENCES workspaces(id),principal text NOT NULL,action text NOT NULL,key text NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,principal,action,key));
CREATE TABLE IF NOT EXISTS audit_events(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),actor text NOT NULL,action text NOT NULL,resource_id text,previous_hash text NOT NULL,event_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS usage_ledger(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),operation_id uuid NOT NULL,metric text NOT NULL,kind text NOT NULL CHECK(kind IN('reserve','consume','release')),units integer NOT NULL CHECK(units>0),price_version text NOT NULL DEFAULT 'unpriced-local-v1',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,operation_id,metric,kind),FOREIGN KEY(workspace_id,operation_id) REFERENCES operations(workspace_id,id));
CREATE TABLE IF NOT EXISTS outbox(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),type text NOT NULL,aggregate_id uuid NOT NULL,data jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS contacts(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),email_original text NOT NULL,email_lookup text NOT NULL,attrs jsonb NOT NULL DEFAULT '{}',subscription text NOT NULL DEFAULT 'pending_confirmation' CHECK(subscription IN('pending_confirmation','subscribed','unsubscribed')),consent_version integer NOT NULL DEFAULT 1,deleted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,email_lookup));
CREATE TABLE IF NOT EXISTS suppressions(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,contact_id,reason),FOREIGN KEY(workspace_id,contact_id) REFERENCES contacts(workspace_id,id));
CREATE TABLE IF NOT EXISTS consent_events(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),contact_id uuid NOT NULL,action text NOT NULL,evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,contact_id) REFERENCES contacts(workspace_id,id));
CREATE TABLE IF NOT EXISTS campaigns(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,revision_id uuid NOT NULL,state text NOT NULL DEFAULT 'draft',version integer NOT NULL DEFAULT 1,intent jsonb NOT NULL,digest text NOT NULL,approval jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,revision_id) REFERENCES revisions(workspace_id,id));
CREATE TABLE IF NOT EXISTS preflights(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),revision_id uuid NOT NULL,artifact_hash text NOT NULL,state text NOT NULL,findings jsonb NOT NULL,profiles jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,revision_id) REFERENCES revisions(workspace_id,id));
CREATE TABLE IF NOT EXISTS api_keys(workspace_id uuid NOT NULL REFERENCES workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),key_hash text NOT NULL UNIQUE,name text NOT NULL,scopes jsonb NOT NULL,created_by text NOT NULL,revoked_at timestamptz,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
ALTER TABLE workspaces FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS workspace_member ON workspaces;
CREATE POLICY workspace_member ON workspaces USING(id::text=current_setting('app.workspace_id',true)) WITH CHECK(id::text=current_setting('app.workspace_id',true));
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS membership_context ON memberships;
CREATE POLICY membership_context ON memberships USING(user_id=current_setting('app.user_id',true) OR workspace_id::text=current_setting('app.workspace_id',true));
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['brands','emails','revisions','operations','idempotency','audit_events','usage_ledger','outbox','contacts','suppressions','consent_events','campaigns','preflights','api_keys'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('DROP POLICY IF EXISTS tenant_context ON %I',t);
  EXECUTE format('CREATE POLICY tenant_context ON %I USING(workspace_id::text=current_setting(''app.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''app.workspace_id'',true))',t);
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA public TO mailcraft_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO mailcraft_runtime;
REVOKE UPDATE,DELETE ON revisions,brands,audit_events,usage_ledger,consent_events FROM mailcraft_runtime;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY,applied_at timestamptz DEFAULT now());
INSERT INTO schema_migrations(version) VALUES('001-foundations') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION mailcraft_due_operations() RETURNS TABLE(workspace_id uuid,id uuid,created_by text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT workspace_id,id,created_by FROM operations WHERE state='queued' ORDER BY created_at LIMIT 50 $$;
REVOKE ALL ON FUNCTION mailcraft_due_operations() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mailcraft_due_operations() TO mailcraft_runtime;
CREATE OR REPLACE FUNCTION mailcraft_create_workspace(p_name text,p_user text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN IF p_user IS DISTINCT FROM current_setting('app.user_id',true) OR p_user='' OR length(p_name)>100 OR length(p_name)<1 THEN RAISE EXCEPTION 'Invalid provisioning principal'; END IF; INSERT INTO workspaces(name) VALUES(p_name) RETURNING id INTO w; INSERT INTO memberships(workspace_id,user_id,role) VALUES(w,p_user,'Owner'); RETURN w; END $$;
REVOKE ALL ON FUNCTION mailcraft_create_workspace(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mailcraft_create_workspace(text,text) TO mailcraft_runtime;
